/* ============================ sheet 组装 ============================ */

type Die = { baseType: string; specialType: string; rangeMin: number; rangeMax: number; effects: string[] }
type Card = { name: string; cost: number; type: string; tags: string[]; effects: string[]; dice: Die[]; egoPassive?: { name: string; effect: string } }
type Page = { name: string; cost: string; effect: string; mechanisms: Mechanism[] }

const RV: Record<string, number> = { n: 1, t: 0.5, w: 1.5, f: 2, r: 0 }
function toResist(vals: number[]) {
  return { physic: { slash: vals[0], pierce: vals[1], strike: vals[2] }, chaos: { slash: vals[3], pierce: vals[4], strike: vals[5] } }
}

function libSheet(name: string, u: any): string {
  const sys = { hasSanity: false, hasEgo: false, hasMind: false, ...(u.sys ?? {}) }
  return JSON.stringify({
    battleSystem: 'lob',
    romanNum: '',
    name,
    hp: u.hp ?? 0,
    stagger: u.stagger ?? 0,
    sanity: 0,
    speedMin: u.speedMin ?? 0,
    speedMax: u.speedMax ?? 0,
    resist: toResist([...u.physic, ...u.chaos]),
    factions: [],
    faction: '',
    passives: (u.passives ?? []) as Passive[],
    mechanisms: (u.mechs ?? []) as Mechanism[],
    cards: { combat: u.combat ?? [], special: u.special ?? [], ego: u.ego ?? [] },
    systemData: sys,
  })
}

const emSheet = (pages: Page[], egoCards: Card[]): string => JSON.stringify({ pages, egoCards })

/* ============================ 楼层 ============================ */

const FLOORS_DEF: Record<string, { name: string; latinName: string; code: string; designation: string; theme: string; receptionType: string; battleSystem: string; sortOrder: number; artwork: string }> = {
  "CT-3": {
    "name": "文学层",
    "latinName": "Litterae",
    "code": "CT-3",
    "designation": "文学层",
    "theme": "橘红、游乐园、鲜血",
    "receptionType": "",
    "battleSystem": "lob",
    "sortOrder": 3,
    "artwork": "/art/turris/floors/ct-3.jpg"
  },
  "CT-4": {
    "name": "艺术层",
    "latinName": "Ars",
    "code": "CT-4",
    "designation": "艺术层",
    "theme": "深绿、长廊、沉沦",
    "receptionType": "",
    "battleSystem": "lob",
    "sortOrder": 4,
    "artwork": "/art/turris/floors/ct-4.jpg"
  }
}


const floorRows = (Object.keys(FLOORS_DEF) as Array<keyof typeof FLOORS_DEF>).map((code) => ({
  ...FLOORS_DEF[code],
  description: PAYLOAD.floors[code].style.join('\n'),
}))

/* ============================ 导入主流程 ============================ */

function main(): void {
  const db = getDb()

  for (const floor of floorRows) {
    const existing = db.prepare(`SELECT id FROM floors WHERE code = ?`).get(floor.code) as { id: number } | undefined
    if (existing) {
      console.log(`[import:ct34] 楼层 ${floor.code} 已存在（id=${existing.id}），该层整批跳过。如需重录请先在编辑器中删除该楼层。`)
      continue
    }

    const tx = db.transaction(() => {
      const info = db
        .prepare(
          `INSERT INTO floors (name, latinName, code, designation, theme, receptionType, battleSystem, description, sortOrder, artwork)
           VALUES (@name, @latinName, @code, @designation, @theme, @receptionType, @battleSystem, @description, @sortOrder, @artwork)`,
        )
        .run(floor)
      const floorId = Number(info.lastInsertRowid)
      console.log(`[import:ct34] 楼层 ${floor.code} ${floor.name} -> id=${floorId}`)

      const libs = PAYLOAD.librarians.filter((r: any) => r.floor === floor.code)
      const rrs = PAYLOAD.rr.filter((r: any) => r.floor === floor.code)
      const insLib = db.prepare(
        `INSERT INTO librarians (name, title, department, role, floorId, rarity, coreColor, affiliation, status, description, sheet, portrait, portraitPreview, sortOrder)
         VALUES (@name, @title, 'turris', 'curator', @floorId, @rarity, '', @affiliation, '在任', '', @sheet, '', '', @sortOrder)`,
      )
      let seq = 0
      for (const r of libs) {
        seq += 1
        // Hod 按用户要求留空位：只建行，不录 sheet 数据
        const sheet = r.title === '文学层崇血者之页' ? '' : libSheet(r.name, r.unit)
        insLib.run({ name: r.name, title: r.title, floorId, rarity: '', affiliation: r.affiliation, sheet, sortOrder: seq })
      }
      for (const r of rrs) {
        seq += 1
        insLib.run({ name: r.name, title: r.title, floorId, rarity: 'RR', affiliation: r.unit.affiliation || '【异常实体】', sheet: libSheet(r.name, r.unit), sortOrder: seq })
      }
      console.log(`[import:ct34] 司书 ${libs.length} + RR ${rrs.length} 条`)

      const ents = PAYLOAD.entities.filter((r: any) => r.floor === floor.code)
      const insEmotion = db.prepare(
        `INSERT INTO emotion_entities (floorId, code, name, sheet, sortOrder) VALUES (@floorId, @code, @name, @sheet, @sortOrder)`,
      )
      for (const r of ents) {
        insEmotion.run({ floorId, code: r.code, name: r.name, sheet: emSheet(r.unit.pages, r.unit.egoCards), sortOrder: r.sortOrder })
      }
      console.log(`[import:ct34] 情感书页实体 ${ents.length} 条`)
    })
    tx()
  }

  closeDb()
  console.log('[import:ct34] 完成。')
}

main()
